def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos(obj, default=(0, 0)):
        if isinstance(obj, (list, tuple)) and len(obj) >= 2:
            return obj[0], obj[1]
        return default

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(a, b):
        return [clamp_step(b[0] - a[0]), clamp_step(b[1] - a[1])]

    def step_away(a, b):
        return [clamp_step(a[0] - b[0]), clamp_step(a[1] - b[1])]

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos(observation.get("self_position"))
    ox, oy = pos(observation.get("opponent_position"))
    s = (sx, sy)
    o = (ox, oy)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(s, o)
        gw = observation.get("grid_width", 0)
        gh = observation.get("grid_height", 0)
        corners = [(0, 0), (0, max(0, gh - 1)), (max(0, gw - 1), 0), (max(0, gw - 1), max(0, gh - 1))]
        target = corners[0]
        best = -1
        for c in corners:
            score = manhattan(c, o)
            if score > best:
                best = score
                target = c
        return step_toward(s, target)

    if env == "territory_control":
        candidates = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        best = None
        best_score = None
        for item in candidates:
            p = pos(item, None)
            if p is None:
                continue
            score = manhattan(s, p)
            if best_score is None or score < best_score:
                best_score = score
                best = p
        if best is not None:
            return step_toward(s, best)
        return step_away(s, o)

    resources = observation.get("resources") or observation.get("resource_positions") or []
    best = None
    best_score = None
    for item in resources:
        p = pos(item, None)
        if p is None:
            continue
        score = manhattan(s, p)
        if best_score is None or score < best_score:
            best_score = score
            best = p
    if best is not None:
        return step_toward(s, best)
    return step_toward(s, o)

